const patch = "*** Begin Patch
*** Update File: C:\Users\Admin\Desktop\jewellery-system-arnav\src\modules\challan\challan.css
@@
 .stage-two-error {
   color: #b91c1c;
   font-size: 13px;
   font-weight: 700;
   margin: 0 24px 14px;
 }
+
+/* Final invoice and payment settlement modals. */
+.settlement-overlay {
+  align-items: center;
+  background: rgb(15 23 42 / 0.58);
+  backdrop-filter: blur(3px);
+  display: flex;
+  inset: 0;
+  justify-content: center;
+  overflow-y: auto;
+  padding: 24px;
+  position: fixed;
+  z-index: 1000;
+}
+.settlement-modal {
+  background: var(--ui-surface, #fff);
+  border: 1px solid var(--ui-border, #dfe4e8);
+  border-radius: 18px;
+  box-shadow: 0 26px 70px rgb(15 23 42 / 0.32);
+  color: var(--ui-text, #172033);
+  max-height: calc(100vh - 48px);
+  max-width: 1080px;
+  overflow: auto;
+  width: 100%;
+}
+.settlement-modal > header {
+  align-items: center;
+  border-bottom: 1px solid var(--ui-border, #dfe4e8);
+  display: flex;
+  gap: 16px;
+  justify-content: space-between;
+  padding: 20px 24px;
+}
+.settlement-modal header p {
+  color: var(--ui-muted, #64748b);
+  font-size: 11px;
+  font-weight: 800;
+  letter-spacing: .1em;
+  margin: 0 0 5px;
+}
+.settlement-modal h3 { font-size: 22px; margin: 0; }
+.settlement-message {
+  background: #eff6ff;
+  border: 1px solid #bfdbfe;
+  border-radius: 10px;
+  color: #1d4ed8;
+  font-size: 14px;
+  font-weight: 650;
+  line-height: 1.45;
+  margin: 18px 24px;
+  padding: 12px 14px;
+}
+.settlement-details {
+  display: grid;
+  gap: 12px;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  margin: 18px 24px;
+}
+.settlement-details span,
+.invoice-totals span,
+.settlement-summary span {
+  background: var(--ui-surface-subtle, #f8fafc);
+  border: 1px solid var(--ui-border, #dfe4e8);
+  border-radius: 9px;
+  display: grid;
+  gap: 5px;
+  min-width: 0;
+  padding: 12px;
+}
+.settlement-details small,
+.invoice-totals small,
+.settlement-invoice small {
+  color: var(--ui-muted, #64748b);
+  font-size: 10px;
+  font-weight: 800;
+  letter-spacing: .06em;
+}
+.settlement-details b { overflow-wrap: anywhere; }
+.settlement-table-wrap {
+  border: 1px solid var(--ui-border, #dfe4e8);
+  border-radius: 10px;
+  margin: 0 24px;
+  overflow: auto;
+}
+.settlement-table-wrap table { border-collapse: collapse; min-width: 860px; width: 100%; }
+.settlement-table-wrap th {
+  background: var(--ui-surface-subtle, #f8fafc);
+  color: var(--ui-muted, #64748b);
+  font-size: 10px;
+  letter-spacing: .04em;
+  padding: 11px 12px;
+  text-align: left;
+  text-transform: uppercase;
+  white-space: nowrap;
+}
+.settlement-table-wrap td { border-top: 1px solid var(--ui-border, #dfe4e8); padding: 11px 12px; }
+.settlement-table-wrap td small { color: var(--ui-muted, #64748b); display: block; margin-top: 3px; }
+.invoice-totals {
+  display: grid;
+  gap: 12px;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  margin: 18px 24px;
+}
+.invoice-totals strong { color: var(--ui-emerald, #15803d); font-size: 18px; }
+.settlement-invoice {
+  align-items: center;
+  background: var(--ui-emerald-soft, #ecfdf5);
+  border: 1px solid var(--ui-emerald, #16a34a);
+  border-radius: 11px;
+  display: grid;
+  gap: 4px;
+  justify-items: center;
+  margin: 18px 24px;
+  padding: 16px;
+  text-align: center;
