import {
  collection,
  doc,
  query,
  runTransaction,
  serverTimestamp,
  where,
} from "firebase/firestore";
import { db } from "../firebase/config";
import { isValidBox, isValidSize, normalizeBox, normalizeSize, sizeSortValue } from "./inventoryRules";

export const PURCHASE_HEADERS = ["Import Ref", "Date", "Vendor Name", "Broker Name", "Total Purchase Weight (ct)", "Amount", "Discount", "Payment Due Days"];
export const PURCHASE_ITEM_HEADERS = ["Import Ref", "Type", "Shape", "Size (mm)", "Weight (ct)", "Pieces", "BOX"];
export const purchaseSku = ({ size, shape, type }) => size && shape && type ? `${size}_${shape}_${type}` : "--";
export const inventoryGroup = (size) => { void sizeSortValue(size); return "Uncategorized"; };
export const asNumber = (value) => Number(value || 0);
export const money = (value) => Number(asNumber(value).toFixed(2));
export const datePlusDays = (date, days) => {
  if (!date) return "";
  const result = new Date(`${date}T00:00:00`);
  result.setDate(result.getDate() + Number(days || 0));
  return Number.isNaN(result.getTime()) ? "" : result.toISOString().slice(0, 10);
};
export const pricingFor = (amount, discount) => {
  const gross = money(amount), percent = Number(discount || 0), discountAmount = money((gross * percent) / 100);
  return { amount: gross, discount: percent, discountAmount, netPayable: money(gross - discountAmount) };
};
export const nextPurchaseCounter = (current = {}) => {
  const series = Number(current.series || 1), number = Number(current.number || 0);
  return number >= 100 ? { series: series + 1, number: 1 } : { series, number: number + 1 };
};
export const purchaseIdFromCounter = ({ series, number }) => `PR-A${series}-${number}`;
export const normalizePurchaseItem = (raw) => ({
  id: raw.id || crypto.randomUUID(),
  type: String(raw.type || "").trim().toUpperCase(),
  shape: String(raw.shape || "").trim().replace(/\b\w/g, (c) => c.toUpperCase()),
  size: normalizeSize(raw.size), weight: asNumber(raw.weight), pieces: asNumber(raw.pieces), box: normalizeBox(raw.box),
});
export const validatePurchaseItem = (raw, allowDimensions) => {
  const item = normalizePurchaseItem(raw), errors = [];
  if (!["CVD", "HP"].includes(item.type)) errors.push("Type must be CVD or HP.");
  if (!item.shape) errors.push("Shape is required.");
  if (!isValidSize(item.size, allowDimensions)) errors.push("Size must be a positive valid size.");
  if (!(item.weight > 0)) errors.push("Weight must be greater than 0.");
  if (raw.pieces === "" || raw.pieces === null || raw.pieces === undefined)
    errors.push("Pieces is required.");
  else if (!Number.isInteger(item.pieces) || item.pieces < 0)
    errors.push("Pieces must be a whole number of 0 or more.");
  if (!isValidBox(item.box)) errors.push("BOX must use letters then numbers, e.g. AB29.");
  return { item, errors };
};
export const purchaseLockedByChallan = (purchase, inventory, challans) => {
  const skus = new Set(inventory.filter((row) => row.sourcePurchaseId === purchase.id).map((row) => row.sku));
  return challans.some((challan) => (challan.items || []).some((item) => skus.has(item.sku)));
};
const counterRef = doc(db, "counters", "purchase");
const linkedInventoryQuery = (purchaseId) =>
  query(collection(db, "inventory"), where("sourcePurchaseId", "==", purchaseId));
const challanUsesInventory = (challans, inventoryDocs) => {
  const skus = new Set(inventoryDocs.map((entry) => entry.data().sku));
  return challans.some((challan) =>
    (challan.data().items || []).some((item) => skus.has(item.sku)),
  );
};

const assertPurchaseIsUnlocked = (purchaseId, inventoryDocs, challans) => {
  if (challanUsesInventory(challans, inventoryDocs))
